import config from './jest.config.js'

const useBuildConfig = {
  ...config,
  // override to use build files
  moduleNameMapper: {}
}

export default useBuildConfig

const fs = require('fs')
const path = require('path')
const { execSync } = require('child_process')
const semver = require('semver')

const packageJsonPath = path.join(__dirname, '../package.json')
const packageJsonData = fs.readFileSync(packageJsonPath, 'utf8')
const packageJson = JSON.parse(packageJsonData)

let version = packageJson.version
const releaseType = process.env.RELEASE_TYPE || 'beta'
const semverType = process.env.SEMVER_TYPE

function bumpVersion(version) {
  if (process.env.DRY_RUN) {
    console.log(`npm version ${version}`)
  } else {
    try {
      execSync(`npm version ${version}`, { stdio: 'inherit' })
    } catch (error) {
      console.error('Failed to execute npm version:', error)
      process.exit(1)
    }
  }
}

if (releaseType === 'beta') {
  if (semver.prerelease(version)) {
    version = semver.inc(version, 'prerelease')
  } else {
    version = semver.inc(version, 'pre' + semverType, 'beta')
  }
} else if (releaseType === 'stable') {
  if (!semverType) {
    console.error('Missing semver type. Expected "patch", "minor" or "major".')
    process.exit(1)
  }
  version = semver.inc(version, semverType)
} else {
  console.error('Invalid release type. Expected "beta" or "stable".')
  process.exit(1)
}

bumpVersion(version)

import { defaultConfigOptions } from './web-preset'
import { IS_SERVER } from './env'
import { UNDEFINED, mergeObjects, noop } from './shared'
import { internalMutate } from './mutate'
import { SWRGlobalState } from './global-state'
import { getTimestamp } from './timestamp'
import * as revalidateEvents from '../events'

import type {
  Cache,
  ScopedMutator,
  RevalidateEvent,
  RevalidateCallback,
  ProviderConfiguration,
  GlobalState,
  Unloader
} from '../types'

const revalidateAllKeys = (
  revalidators: Record<string, RevalidateCallback[]>,
  type: RevalidateEvent
) => {
  for (const key in revalidators) {
    if (revalidators[key][0]) revalidators[key][0](type)
  }
}

export const initCache = <Data = any>(
  provider: Cache<Data>,
  options?: Partial<ProviderConfiguration>
):
  | [Cache<Data>, ScopedMutator, () => void, () => void, Unloader]
  | [Cache<Data>, ScopedMutator, undefined, undefined, Unloader]
  | undefined => {
  // The global state for a specific provider will be used to deduplicate
  // requests and store listeners. As well as a mutate function that is bound to
  // the cache.

  // The provider's global state might be already initialized. Let's try to get the
  // global state associated with the provider first.
  if (!SWRGlobalState.has(provider)) {
    const opts = mergeObjects(defaultConfigOptions, options)

    // If there's no global state bound to the provider, create a new one with the
    // new mutate function.
    const EVENT_REVALIDATORS = Object.create(null)

    const mutate = internalMutate.bind(UNDEFINED, provider) as ScopedMutator
    let unmount = noop

    const subscriptions: Record<string, ((current: any, prev: any) => void)[]> =
      Object.create(null)
    const subscribe = (
      key: string,
      callback: (current: any, prev: any) => void
    ) => {
      const subs = subscriptions[key] || []
      subscriptions[key] = subs

      subs.push(callback)
      return () => {
        const index = subs.indexOf(callback)
        if (index >= 0) {
          // O(1): swap with the last element and pop
          subs[index] = subs[subs.length - 1]
          subs.pop()
        }
      }
    }
    const setter = (key: string, value: any, prev: any) => {
      provider.set(key, value)
      const subs = subscriptions[key]
      if (subs) {
        for (const fn of subs) {
          fn(value, prev)
        }
      }
    }

    const unload: Unloader = unloadOptions => {
      const state = SWRGlobalState.get(provider) as GlobalState
      const [, MUTATION, FETCH, PRELOAD] = state
      const ts = getTimestamp()

      // Bump the unload generation so in-flight writes that bypass the
      // request markers (e.g. `useSWRInfinite` page responses) know to
      // discard themselves when they resolve.
      state[8]++

      // Invalidate all in-flight requests and mutations first, so nothing
      // that resolves after this point can write back to the cache: fetches
      // fail the concurrent request marker check, and mutations fail the
      // timestamp race check. Mutation timestamps are overwritten instead of
      // deleted because ongoing mutations read them on resolution.
      for (const key in FETCH) delete FETCH[key]
      for (const key in PRELOAD) delete PRELOAD[key]
      for (const key in MUTATION) MUTATION[key] = [ts, ts]

      // Delete all entries — including the special `useSWRInfinite` and
      // `useSWRSubscription` keys — and notify the subscribers of each key
      // so mounted hooks re-render with the empty cache. Subscribers receive
      // the same empty state object that cache reads resolve to for missing
      // entries.
      const emptyState = {}
      for (const key of [...provider.keys()]) {
        const prev = provider.get(key)
        provider.delete(key)
        const subs = subscriptions[key]
        if (subs) {
          for (const fn of subs) {
            fn(emptyState, prev)
          }
        }
      }

      // The unload event runs last so the fresh requests it may start are
      // not invalidated by the cleanup above. It always fires — even without
      // revalidation — and to every hook on the key, so each one can drop
      // the previous data kept by `keepPreviousData`. Only the first hook
      // revalidates, consistent with how mutations revalidate a key.
      const revalidate = !unloadOptions || unloadOptions.revalidate !== false
      for (const key in EVENT_REVALIDATORS) {
        const revalidators = EVENT_REVALIDATORS[key]
        for (let i = 0; i < revalidators.length; i++) {
          revalidators[i](revalidateEvents.UNLOAD_EVENT, {
            revalidate: revalidate && !i
          })
        }
      }
    }

    const initProvider = () => {
      if (!SWRGlobalState.has(provider)) {
        // Update the state if it's new, or if the provider has been extended.
        SWRGlobalState.set(provider, [
          EVENT_REVALIDATORS,
          Object.create(null),
          Object.create(null),
          Object.create(null),
          mutate,
          setter,
          subscribe,
          unload,
          0
        ])
        if (!IS_SERVER) {
          // When listening to the native events for auto revalidations,
          // we intentionally put a delay (setTimeout) here to make sure they are
          // fired after immediate JavaScript executions, which can be
          // React's state updates.
          // This avoids some unnecessary revalidations such as
          // https://github.com/vercel/swr/issues/1680.
          const releaseFocus = opts.initFocus(
            setTimeout.bind(
              UNDEFINED,
              revalidateAllKeys.bind(
                UNDEFINED,
                EVENT_REVALIDATORS,
                revalidateEvents.FOCUS_EVENT
              )
            )
          )
          const releaseReconnect = opts.initReconnect(
            setTimeout.bind(
              UNDEFINED,
              revalidateAllKeys.bind(
                UNDEFINED,
                EVENT_REVALIDATORS,
                revalidateEvents.RECONNECT_EVENT
              )
            )
          )
          unmount = () => {
            // eslint-disable-next-line @typescript-eslint/no-unused-expressions
            releaseFocus && releaseFocus()
            // eslint-disable-next-line @typescript-eslint/no-unused-expressions
            releaseReconnect && releaseReconnect()
            // When un-mounting, we need to remove the cache provider from the state
            // storage too because it's a side-effect. Otherwise, when re-mounting we
            // will not re-register those event listeners.
            SWRGlobalState.delete(provider)
          }
        }
      }
    }
    initProvider()

    // This is a new provider, we need to initialize it and setup DOM events
    // listeners for `focus` and `reconnect` actions.

    // We might want to inject an extra layer on top of `provider` in the future,
    // such as key serialization, auto GC, etc.
    // For now, it's just a `Map` interface without any modifications.
    return [provider, mutate, initProvider, unmount, unload]
  }

  const state = SWRGlobalState.get(provider) as GlobalState
  return [provider, state[4], UNDEFINED, UNDEFINED, state[7]]
}

'use client'

import type { FC, PropsWithChildren } from 'react'
import {
  createContext,
  createElement,
  useContext,
  useMemo,
  useRef
} from 'react'
import { cache as defaultCache } from './config'
import { initCache } from './cache'
import { mergeConfigs } from './merge-config'
import { UNDEFINED, mergeObjects, isFunction } from './shared'
import { useIsomorphicLayoutEffect } from './env'
import type { SWRConfigValue, FullConfiguration } from '../types'

export const SWRConfigContext = createContext<Partial<FullConfiguration>>({})

const SWRConfig: FC<
  PropsWithChildren<{
    value?: SWRConfigValue | ((parentConfig?: SWRConfigValue) => SWRConfigValue)
  }>
> = props => {
  const { value } = props
  const parentConfig = useContext(SWRConfigContext)
  const isFunctionalConfig = isFunction(value)
  const config = useMemo(
    () => (isFunctionalConfig ? value(parentConfig as SWRConfigValue) : value),
    [isFunctionalConfig, parentConfig, value]
  )
  // Extend parent context values and middleware.
  const extendedConfig = useMemo(
    () => (isFunctionalConfig ? config : mergeConfigs(parentConfig, config)),
    [isFunctionalConfig, parentConfig, config]
  )

  // Should not use the inherited provider.
  const provider = config && config.provider

  // initialize the cache only on first access.
  const cacheContextRef = useRef<ReturnType<typeof initCache>>(UNDEFINED)
  if (provider && !cacheContextRef.current) {
    cacheContextRef.current = initCache(
      provider((extendedConfig as any).cache || defaultCache),
      config
    )
  }
  const cacheContext = cacheContextRef.current

  // Override the cache if a new provider is given.
  if (cacheContext) {
    ;(extendedConfig as any).cache = cacheContext[0]
    ;(extendedConfig as any).mutate = cacheContext[1]
    ;(extendedConfig as any).unload = cacheContext[4]
  }

  // Unsubscribe events.
  useIsomorphicLayoutEffect(() => {
    if (cacheContext) {
      // eslint-disable-next-line @typescript-eslint/no-unused-expressions
      cacheContext[2] && cacheContext[2]()
      return cacheContext[3]
    }
  }, [])

  return createElement(
    SWRConfigContext.Provider,
    mergeObjects(props, {
      value: extendedConfig
    })
  )
}

export default SWRConfig

import type {
  PublicConfiguration,
  FullConfiguration,
  RevalidatorOptions,
  Revalidator,
  ScopedMutator,
  Cache,
  Unloader
} from '../types'

import { initCache } from './cache'
import { preset } from './web-preset'
import { slowConnection } from './env'
import { isUndefined, noop, mergeObjects } from './shared'

import { dequal } from 'dequal/lite'

// error retry
const onErrorRetry = (
  _: unknown,
  __: string,
  config: Readonly<PublicConfiguration>,
  revalidate: Revalidator,
  opts: Required<RevalidatorOptions>
): void => {
  const maxRetryCount = config.errorRetryCount
  const currentRetryCount = opts.retryCount

  // Exponential backoff
  const timeout =
    ~~(
      (Math.random() + 0.5) *
      (1 << (currentRetryCount < 8 ? currentRetryCount : 8))
    ) * config.errorRetryInterval

  if (!isUndefined(maxRetryCount) && currentRetryCount > maxRetryCount) {
    return
  }

  setTimeout(revalidate, timeout, opts)
}

const compare = dequal

// Default cache provider
const [cache, mutate, , , unload] = initCache(new Map()) as [
  Cache<any>,
  ScopedMutator,
  unknown,
  unknown,
  Unloader
]
export { cache, mutate, unload, compare }

// Default config
export const defaultConfig: FullConfiguration = mergeObjects(
  {
    // events
    onLoadingSlow: noop,
    onSuccess: noop,
    onError: noop,
    onErrorRetry,
    onDiscarded: noop,

    // switches
    revalidateOnFocus: true,
    revalidateOnReconnect: true,
    revalidateIfStale: true,
    shouldRetryOnError: true,

    // timeouts
    errorRetryInterval: slowConnection ? 10000 : 5000,
    focusThrottleInterval: 5 * 1000,
    dedupingInterval: 2 * 1000,
    loadingTimeout: slowConnection ? 5000 : 3000,

    // providers
    compare,
    isPaused: () => false,
    cache,
    mutate,
    unload,
    fallback: {}
  },
  // use web preset by default
  preset
)

import React from 'react'
import { isWindowDefined } from './helper'

// @ts-expect-error
const enableDevtools = isWindowDefined && window.__SWR_DEVTOOLS_USE__

export const use = enableDevtools
  ? // @ts-expect-error
    window.__SWR_DEVTOOLS_USE__
  : []

export const setupDevTools = () => {
  if (enableDevtools) {
    // @ts-expect-error
    window.__SWR_DEVTOOLS_REACT__ = React
  }
}

import React, { useEffect, useLayoutEffect } from 'react'
import {
  hasRequestAnimationFrame,
  isLegacyDeno,
  isWindowDefined
} from './helper'

export const IS_REACT_LEGACY = !React.useId

export const IS_SERVER = !isWindowDefined || isLegacyDeno

// Polyfill requestAnimationFrame
export const rAF = (
  f: (...args: any[]) => void
): number | ReturnType<typeof setTimeout> =>
  hasRequestAnimationFrame()
    ? window['requestAnimationFrame'](f)
    : setTimeout(f, 1)

// React currently throws a warning when using useLayoutEffect on the server.
// To get around it, we can conditionally useEffect on the server (no-op) and
// useLayoutEffect in the browser.
export const useIsomorphicLayoutEffect = IS_SERVER ? useEffect : useLayoutEffect

// This assignment is to extend the Navigator type to use effectiveType.
const navigatorConnection =
  typeof navigator !== 'undefined' &&
  (
    navigator as Navigator & {
      connection?: {
        effectiveType: string
        saveData: boolean
      }
    }
  ).connection

// Adjust the config based on slow connection status (<= 70Kbps).
export const slowConnection =
  !IS_SERVER &&
  navigatorConnection &&
  (['slow-2g', '2g'].includes(navigatorConnection.effectiveType) ||
    navigatorConnection.saveData)

import type { Cache, GlobalState } from '../types'

// Global state used to deduplicate requests and store listeners
export const SWRGlobalState = new WeakMap<Cache, GlobalState>()

import { OBJECT, isUndefined } from './shared'

// use WeakMap to store the object->key mapping
// so the objects can be garbage collected.
// WeakMap uses a hashtable under the hood, so the lookup
// complexity is almost O(1).
const table = new WeakMap<object, number | string>()

const getTypeName = (value: any) => OBJECT.prototype.toString.call(value)

const isObjectTypeName = (typeName: string, type: string) =>
  typeName === `[object ${type}]`

// counter of the key
let counter = 0

// A stable hash implementation that supports:
// - Fast and ensures unique hash properties
// - Handles unserializable values
// - Handles object key ordering
// - Generates short results
//
// This is not a serialization function, and the result is not guaranteed to be
// parsable.
export const stableHash = (arg: any): string => {
  const type = typeof arg
  const typeName = getTypeName(arg)
  const isDate = isObjectTypeName(typeName, 'Date')
  const isRegex = isObjectTypeName(typeName, 'RegExp')
  const isPlainObject = isObjectTypeName(typeName, 'Object')
  let result: any
  let index: any

  if (OBJECT(arg) === arg && !isDate && !isRegex) {
    // Object/function, not null/date/regexp. Use WeakMap to store the id first.
    // If it's already hashed, directly return the result.
    result = table.get(arg)
    if (result) return result

    // Store the hash first for circular reference detection before entering the
    // recursive `stableHash` calls.
    // For other objects like set and map, we use this id directly as the hash.
    result = ++counter + '~'
    table.set(arg, result)

    if (Array.isArray(arg)) {
      // Array.
      result = '@'
      for (index = 0; index < arg.length; index++) {
        result += stableHash(arg[index]) + ','
      }
      table.set(arg, result)
    }
    if (isPlainObject) {
      // Object, sort keys.
      result = '#'
      const keys = OBJECT.keys(arg).sort()
      while (!isUndefined((index = keys.pop() as string))) {
        if (!isUndefined(arg[index])) {
          result += index + ':' + stableHash(arg[index]) + ','
        }
      }
      table.set(arg, result)
    }
  } else {
    result = isDate
      ? arg.toJSON()
      : type == 'symbol'
        ? arg.toString()
        : type == 'string'
          ? JSON.stringify(arg)
          : '' + arg
  }

  return result
}

import type { Cache, State, GlobalState } from '../types'
import { SWRGlobalState } from './global-state'
import { isUndefined, mergeObjects } from './shared'

const EMPTY_CACHE = {}
const INITIAL_CACHE: Record<string, any> = {}

const STR_UNDEFINED = 'undefined'

// NOTE: Use the function to guarantee it's re-evaluated between jsdom and node runtime for tests.
export const isWindowDefined = typeof window != STR_UNDEFINED
export const isDocumentDefined = typeof document != STR_UNDEFINED
export const isLegacyDeno = isWindowDefined && 'Deno' in window

export const hasRequestAnimationFrame = () =>
  isWindowDefined && typeof window['requestAnimationFrame'] != STR_UNDEFINED

export const createCacheHelper = <Data = any, T = State<Data, any>>(
  cache: Cache,
  key: string | undefined
) => {
  const state = SWRGlobalState.get(cache) as GlobalState
  return [
    // Getter
    () => ((!isUndefined(key) && cache.get(key)) || EMPTY_CACHE) as T,
    // Setter
    (info: T) => {
      if (!isUndefined(key)) {
        const prev = cache.get(key)

        // Before writing to the store, we keep the value in the initial cache
        // if it's not there yet.
        if (!(key in INITIAL_CACHE)) {
          INITIAL_CACHE[key] = prev
        }

        state[5](key, mergeObjects(prev, info), prev || EMPTY_CACHE)
      }
    },
    // Subscriber
    state[6],
    // Get server cache snapshot
    () => {
      if (!isUndefined(key)) {
        // If the cache was updated on the client, we return the stored initial value.
        if (key in INITIAL_CACHE) return INITIAL_CACHE[key]
      }

      // If we haven't done any client-side updates, we return the current value.
      return ((!isUndefined(key) && cache.get(key)) || EMPTY_CACHE) as T
    }
  ] as const
}

// export { UNDEFINED, OBJECT, isUndefined, isFunction, mergeObjects, isPromiseLike }

import { mergeObjects } from './shared'
import type { FullConfiguration } from '../types'

export const mergeConfigs = (
  a: Partial<FullConfiguration>,
  b?: Partial<FullConfiguration>
) => {
  // Need to create a new object to avoid mutating the original here.
  const v: Partial<FullConfiguration> = mergeObjects(a, b)

  // If two configs are provided, merge their `use`, `fallback`, and
  // `cacheData` options.
  if (b) {
    const { use: u1, fallback: f1, cacheData: c1 } = a
    const { use: u2, fallback: f2, cacheData: c2 } = b
    if (u1 && u2) {
      v.use = u1.concat(u2)
    }
    if (f1 && f2) {
      v.fallback = mergeObjects(f1, f2)
    }
    if (c1 && c2) {
      v.cacheData = mergeObjects(c1, c2)
    }
  }

  return v
}

import { use as devtoolsUse } from './devtools'
import { middleware as preload } from './preload'

export const BUILT_IN_MIDDLEWARE = devtoolsUse.concat(preload)

import { serialize } from './serialize'
import { createCacheHelper } from './helper'
import {
  isFunction,
  isUndefined,
  UNDEFINED,
  mergeObjects,
  isPromiseLike
} from './shared'
import { SWRGlobalState } from './global-state'
import { getTimestamp } from './timestamp'
import * as revalidateEvents from '../events'
import type {
  Cache,
  MutatorCallback,
  MutatorOptions,
  GlobalState,
  State,
  Arguments,
  Key
} from '../types'

type KeyFilter = (key?: Arguments) => boolean
type MutateState<Data> = State<Data, any> & {
  // The previously committed data.
  _c?: Data
}

export async function internalMutate<Data>(
  cache: Cache,
  _key: KeyFilter,
  _data?: Data | Promise<Data | undefined> | MutatorCallback<Data>,
  _opts?: boolean | MutatorOptions<Data>
): Promise<Array<Data | undefined>>
export async function internalMutate<Data>(
  cache: Cache,
  _key: Arguments,
  _data?: Data | Promise<Data | undefined> | MutatorCallback<Data>,
  _opts?: boolean | MutatorOptions<Data>
): Promise<Data | undefined>
export async function internalMutate<Data>(
  ...args: [
    cache: Cache,
    _key: KeyFilter | Arguments,
    _data?: Data | Promise<Data | undefined> | MutatorCallback<Data>,
    _opts?: boolean | MutatorOptions<Data>
  ]
): Promise<any> {
  const [cache, _key, _data, _opts] = args

  // When passing as a boolean, it's explicitly used to disable/enable
  // revalidation.
  const options = mergeObjects(
    { populateCache: true, throwOnError: true },
    typeof _opts === 'boolean' ? { revalidate: _opts } : _opts || {}
  )

  let populateCache = options.populateCache

  const rollbackOnErrorOption = options.rollbackOnError
  let optimisticData = options.optimisticData

  const rollbackOnError = (error: unknown): boolean => {
    return typeof rollbackOnErrorOption === 'function'
      ? rollbackOnErrorOption(error)
      : rollbackOnErrorOption !== false
  }
  const throwOnError = options.throwOnError

  // If the second argument is a key filter, return the mutation results for all
  // filtered keys.
  if (isFunction(_key)) {
    const keyFilter = _key
    const matchedKeys: Key[] = []
    const it = cache.keys()
    for (const key of it) {
      if (
        // Skip the special useSWRInfinite and useSWRSubscription keys.
        !/^\$(inf|sub)\$/.test(key) &&
        keyFilter((cache.get(key) as { _k: Arguments })._k)
      ) {
        matchedKeys.push(key)
      }
    }
    return Promise.all(matchedKeys.map(mutateByKey))
  }

  return mutateByKey(_key)

  async function mutateByKey(_k: Key): Promise<Data | undefined> {
    // Serialize key
    const [key] = serialize(_k)
    if (!key) return
    const [get, set] = createCacheHelper<Data, MutateState<Data>>(cache, key)
    const [EVENT_REVALIDATORS, MUTATION, FETCH, PRELOAD] = SWRGlobalState.get(
      cache
    ) as GlobalState

    const startRevalidate = () => {
      const revalidators = EVENT_REVALIDATORS[key]
      const revalidate = isFunction(options.revalidate)
        ? options.revalidate(get().data, _k)
        : options.revalidate !== false
      if (revalidate) {
        // Invalidate the key by deleting the concurrent request markers so new
        // requests will not be deduped.
        delete FETCH[key]
        delete PRELOAD[key]
        if (revalidators && revalidators[0]) {
          return revalidators[0](revalidateEvents.MUTATE_EVENT).then(
            () => get().data
          )
        }
      }
      return get().data
    }

    // If there is no new data provided, revalidate the key with current state.
    if (args.length < 3) {
      // Revalidate and broadcast state.
      return startRevalidate()
    }

    let data: any = _data
    let error: unknown
    let isError = false

    // Update global timestamps.
    const beforeMutationTs = getTimestamp()
    MUTATION[key] = [beforeMutationTs, 0]

    const hasOptimisticData = !isUndefined(optimisticData)
    const state = get()

    // `displayedData` is the current value on screen. It could be the optimistic value
    // that is going to be overridden by a `committedData`, or get reverted back.
    // `committedData` is the validated value that comes from a fetch or mutation.
    const displayedData = state.data
    const currentData = state._c
    const committedData = isUndefined(currentData) ? displayedData : currentData

    // Do optimistic data update.
    if (hasOptimisticData) {
      optimisticData = isFunction(optimisticData)
        ? optimisticData(committedData, displayedData)
        : optimisticData

      // When we set optimistic data, backup the current committedData data in `_c`.
      set({ data: optimisticData, _c: committedData })
    }

    if (isFunction(data)) {
      // `data` is a function, call it passing current cache value.
      try {
        data = (data as MutatorCallback<Data>)(committedData)
      } catch (err) {
        // If it throws an error synchronously, we shouldn't update the cache.
        error = err
        isError = true
      }
    }

    // `data` is a promise/thenable, resolve the final data first.
    if (data && isPromiseLike(data)) {
      // This means that the mutation is async, we need to check timestamps to
      // avoid race conditions.
      data = await (data as Promise<Data>).catch(err => {
        error = err
        isError = true
      })

      // Check if other mutations have occurred since we've started this mutation.
      // If there's a race we don't update cache or broadcast the change,
      // just return the data.
      if (beforeMutationTs !== MUTATION[key][0]) {
        if (isError) throw error
        return data
      } else if (isError && hasOptimisticData && rollbackOnError(error)) {
        // Rollback. Always populate the cache in this case but without
        // transforming the data.
        populateCache = true

        // Reset data to be the latest committed data, and clear the `_c` value.
        set({ data: committedData, _c: UNDEFINED })
      }
    }

    // If we should write back the cache after request.
    if (populateCache) {
      if (!isError) {
        // Transform the result into data.
        if (isFunction(populateCache)) {
          const populateCachedData = populateCache(data, committedData)
          set({ data: populateCachedData, error: UNDEFINED, _c: UNDEFINED })
        } else {
          // Only update cached data and reset the error if there's no error. Data can be `undefined` here.
          set({ data, error: UNDEFINED, _c: UNDEFINED })
        }
      }
    }

    // Reset the timestamp to mark the mutation has ended.
    MUTATION[key][1] = getTimestamp()

    // Update existing SWR Hooks' internal states:
    Promise.resolve(startRevalidate()).then(() => {
      // The mutation and revalidation are ended, we can clear it since the data is
      // not an optimistic value anymore.
      set({ _c: UNDEFINED })
    })

    // Throw error or return data
    if (isError) {
      if (throwOnError) throw error
      return
    }
    return data
  }
}

import { isFunction } from './shared'

import type { Key, Fetcher, SWRConfiguration } from '../types'

export const normalize = <KeyType = Key, Data = any>(
  args:
    | [KeyType]
    | [KeyType, Fetcher<Data> | null]
    | [KeyType, SWRConfiguration | undefined]
    | [KeyType, Fetcher<Data> | null, SWRConfiguration | undefined]
): [KeyType, Fetcher<Data> | null, Partial<SWRConfiguration<Data>>] => {
  return isFunction(args[1])
    ? [args[0], args[1], args[2] || {}]
    : [args[0], null, (args[1] === null ? args[2] : args[1]) || {}]
}

import type {
  Middleware,
  Key,
  BareFetcher,
  GlobalState,
  FetcherResponse
} from '../types'
import { serialize } from './serialize'
import { cache } from './config'
import { SWRGlobalState } from './global-state'
import { isUndefined } from './shared'
import { INFINITE_PREFIX } from '../constants'
import { IS_SERVER } from './env'

// Basically same as Fetcher but without Conditional Fetching
type PreloadFetcher<
  Data = unknown,
  SWRKey extends Key = Key
> = SWRKey extends () => infer Arg
  ? (arg: Arg) => FetcherResponse<Data>
  : SWRKey extends infer Arg
    ? (arg: Arg) => FetcherResponse<Data>
    : never

export const preload = <
  Data = any,
  SWRKey extends Key = Key,
  Fetcher extends BareFetcher = PreloadFetcher<Data, SWRKey>
>(
  key_: SWRKey,
  fetcher: Fetcher
): ReturnType<Fetcher> => {
  // preload should be a no-op on the server
  if (IS_SERVER) {
    return undefined as ReturnType<Fetcher>
  }

  const [key, fnArg] = serialize(key_)
  const [, , , PRELOAD] = SWRGlobalState.get(cache) as GlobalState

  // Prevent preload to be called multiple times before used.
  if (PRELOAD[key]) {
    return PRELOAD[key] as ReturnType<Fetcher>
  }

  const req = fetcher(fnArg) as ReturnType<Fetcher>
  PRELOAD[key] = req
  return req
}

export const middleware: Middleware =
  useSWRNext => (key_, fetcher_, config) => {
    // fetcher might be a sync function, so this should not be an async function
    const fetcher =
      fetcher_ &&
      ((...args: any[]) => {
        const [key] = serialize(key_)
        const [, , , PRELOAD] = SWRGlobalState.get(cache) as GlobalState

        if (key.startsWith(INFINITE_PREFIX)) {
          // we want the infinite fetcher to be called.
          // handling of the PRELOAD cache happens there.
          return fetcher_(...args)
        }

        const req = PRELOAD[key]
        if (isUndefined(req)) return fetcher_(...args)
        delete PRELOAD[key]
        return req
      })
    return useSWRNext(key_, fetcher, config)
  }

import { mergeConfigs } from './merge-config'
import { normalize } from './normalize-args'
import { useSWRConfig } from './use-swr-config'
import { BUILT_IN_MIDDLEWARE } from './middleware-preset'

// It's tricky to pass generic types as parameters, so we just directly override
// the types here.
export const withArgs = <SWRType>(hook: any) => {
  return function useSWRArgs(...args: any) {
    // Get the default and inherited configuration.
    const fallbackConfig = useSWRConfig()

    // Normalize arguments.
    const [key, fn, _config] = normalize<any, any>(args)

    // Merge configurations.
    const config = mergeConfigs(fallbackConfig, _config)

    // Apply middleware
    let next = hook
    const { use } = config
    const middleware = (use || []).concat(BUILT_IN_MIDDLEWARE)
    for (let i = middleware.length; i--; ) {
      next = middleware[i](next)
    }

    return next(key, fn || config.fetcher || null, config)
  } as unknown as SWRType
}

import { stableHash } from './hash'
import { isFunction } from './shared'

import type { Key, Arguments } from '../types'

export const serialize = (key: Key): [string, Arguments] => {
  if (isFunction(key)) {
    try {
      key = key()
    } catch (err) {
      // dependencies not ready
      key = ''
    }
  }

  // Use the original key as the argument of fetcher. This can be a string or an
  // array of values.
  const args = key

  // If key is not falsy, or not an empty array, hash it.
  key =
    typeof key == 'string'
      ? key
      : (Array.isArray(key) ? key.length : key)
        ? stableHash(key)
        : ''

  return [key, args]
}

