const use =
  React.use ||
  // This extra generic is to avoid TypeScript mixing up the generic and JSX sytax
  // and emitting an error.
  // We assume that this is only for the `use(thenable)` case, not `use(context)`.
  // https://github.com/facebook/react/blob/aed00dacfb79d17c53218404c52b1c7aa59c4a89/packages/react-server/src/ReactFizzThenable.js#L45
  (<T, _>(
    thenable: Promise<T> & {
      status?: 'pending' | 'fulfilled' | 'rejected'
      value?: T
      reason?: unknown
    }
  ): T => {
    switch (thenable.status) {
      case 'pending':
        throw thenable
      case 'fulfilled':
        return thenable.value as T
      case 'rejected':
        throw thenable.reason
      default:
        thenable.status = 'pending'
        thenable.then(
          v => {
            thenable.status = 'fulfilled'
            thenable.value = v
          },
          e => {
            thenable.status = 'rejected'
            thenable.reason = e
          }
        )
        throw thenable
    }
  })

const WITH_DEDUPE = { dedupe: true }

type ConsumedCacheData = WeakMap<CacheData, Set<string>>

const isCacheDataConsumed = (
  consumedCacheData: ConsumedCacheData,
  cacheData: CacheData | undefined,
  key: string
) => (cacheData ? consumedCacheData.get(cacheData)?.has(key) === true : false)

const markCacheDataConsumed = (
  consumedCacheData: ConsumedCacheData,
  cacheData: CacheData | undefined,
  key: string
) => {
  if (!cacheData) return

  let consumedKeys = consumedCacheData.get(cacheData)
  if (!consumedKeys) {
    consumedKeys = new Set()
    consumedCacheData.set(cacheData, consumedKeys)
  }
  consumedKeys.add(key)
}

const commitCacheData = <Data>({
  value,
  getCacheData,
  canCommit,
  setCache
}: {
  value: CacheData<Data>[string]
  getCacheData: () => Data | undefined
  canCommit: () => boolean
  setCache: (
    state: { data: Data; error: undefined } | { error: unknown }
  ) => void
}) => {
  const commit = (
    state: { data: Data; error: undefined } | { error: unknown }
  ) => {
    if (canCommit() && isUndefined(getCacheData())) {
      setCache(state)
    }
  }

  Promise.resolve(value).then(
    data => {
      commit({ data, error: UNDEFINED })
    },
    error => {
      commit({ error })
    }
  )
}

export const useSWRHandler = <Data = any, Error = any>(
  _key: Key,
  fetcher: Fetcher<Data> | null,
  config: FullConfiguration
) => {
  const {
    cache,
    compare,
    suspense,
    fallbackData,
    revalidateOnMount,
    revalidateIfStale,
    refreshInterval,
    refreshWhenHidden,
    refreshWhenOffline,
    keepPreviousData,
    strictServerPrefetchWarning
  } = config

  const [EVENT_REVALIDATORS, MUTATION, FETCH, PRELOAD] = SWRGlobalState.get(
    cache
  ) as GlobalState

  // `key` is the identifier of the SWR internal state,
  // `fnArg` is the argument/arguments parsed from the key, which will be passed
  // to the fetcher.
  // All of them are derived from `_key`.
  const [key, fnArg] = serialize(_key)

  // If it's the initial render of this hook.
  const initialMountedRef = useRef(false)

  // If the hook is unmounted already. This will be used to prevent some effects
  // to be called after unmounting.
  const unmountedRef = useRef(false)

  // Refs to keep the key and config.
  const keyRef = useRef(key)
  const fetcherRef = useRef(fetcher)
  const configRef = useRef(config)
  const getConfig = () => configRef.current
  const isActive = () => getConfig().isVisible() && getConfig().isOnline()

  const [getCache, setCache, subscribeCache, getInitialCache] =
    createCacheHelper<
      Data,
      State<Data, any> & {
        // The original key arguments.
        _k?: Key
      }
    >(cache, key)

  const stateDependencies = useRef<StateDependencies>({}).current

  // Resolve the fallback data from either the inline option, or the global provider.
  // If it's a promise, we simply let React suspend and resolve it for us.
  const fallback = isUndefined(fallbackData)
    ? isUndefined(config.fallback)
      ? UNDEFINED
      : config.fallback[key]
    : fallbackData
  const serverCacheData = config.cacheData
  const configCacheData = !key ? UNDEFINED : serverCacheData?.[key]
  const req = key ? PRELOAD[key] : UNDEFINED
  // `cacheData` is request-scoped data provided by a Server Component through
  // `SWRConfig`'s context. It's only used when there's no in-flight client
  // `preload()` response (`req`) for the same key.
  const hasCacheData = isUndefined(req) && !isUndefined(configCacheData)
  const preloadedData = hasCacheData ? configCacheData : req

  const isEqual = (prev: State<Data, any>, current: State<Data, any>) => {
    for (const _ in stateDependencies) {
      const t = _ as keyof StateDependencies
      if (t === 'data') {
        if (!compare(prev[t], current[t])) {
          if (!isUndefined(prev[t])) {
            return false
          }
          if (!compare(returnedData, current[t])) {
            return false

        }
      }
    } else {
      if (current[t] !== prev[t]) {
        return false
      }
    }
  }
  return true
}
const isInitialMount = !initialMountedRef.current
const getSnapshot = useMemo(() => {
  const cachedData = getCache()
  const initialData = getInitialCache()
  const getSelectedCache = (state: ReturnType<typeof getCache>) => {
    // We only select the needed fields from the state.
    const snapshot = mergeObjects(state)
    delete snapshot._k

    const shouldStartRequest = (() => {
      if (!key) return false
      if (!fetcher) return false
      // If it's paused, we skip revalidation.
      if (getConfig().isPaused()) return false
      // If `revalidateOnMount` is set, we take the value directly.
      if (isInitialMount && !isUndefined(revalidateOnMount))
        return revalidateOnMount
      const data = !isUndefined(fallback) ? fallback : snapshot.data
      // cacheData is consumed during the initial Suspense render. Once data
      // is cached, fall through to the normal mount revalidation policy.
      if (suspense && hasCacheData && isUndefined(data)) return false
      if (suspense) return isUndefined(data) || revalidateIfStale
      return isUndefined(data) || revalidateIfStale
    })()

    if (!shouldStartRequest) {
      return snapshot
    }

    return {
      isValidating: true,
      isLoading: true,
      ...snapshot
    }
  }

  const clientSnapshot = getSelectedCache(cachedData)
  const serverSnapshot =
    cachedData === initialData
      ? clientSnapshot
      : getSelectedCache(initialData)
  // To make sure that we are returning the same object reference to avoid
  // unnecessary re-renders, we keep the previous snapshot and use deep
  // comparison to check if we need to return a new one.
  let memorizedSnapshot = clientSnapshot

  return [
    () => {
      const newSnapshot = getSelectedCache(getCache())
      const compareResult = isEqual(newSnapshot, memorizedSnapshot)

      if (compareResult) {
        // Mentally, we should always return the `memorizedSnapshot` here
        // as there's no change between the new and old snapshots.
        // However, since the `isEqual` function only compares selected fields,
        // the values of the unselected fields might be changed. That's
        // simply because we didn't track them.
        // To support the case in https://github.com/vercel/swr/pull/2576,
        // we need to update these fields in the `memorizedSnapshot` too
        // with direct mutations to ensure the snapshot is always up-to-date
        // even for the unselected fields, but only trigger re-renders when
        // the selected fields are changed.
        memorizedSnapshot.data = newSnapshot.data
        memorizedSnapshot.isLoading = newSnapshot.isLoading
        memorizedSnapshot.isValidating = newSnapshot.isValidating
        memorizedSnapshot.error = newSnapshot.error
        return memorizedSnapshot
      } else {
        memorizedSnapshot = newSnapshot
        return newSnapshot

      }
    },
    () => serverSnapshot
  ]
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [cache, key])

// Get the current state that SWR should return.
const cached = useSyncExternalStore(
  useCallback(
    (callback: () => void) =>
      subscribeCache(
        key,
        (current: State<Data, any>, prev: State<Data, any>) => {
          if (!isEqual(prev, current)) callback()
        }
      ),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [cache, key]
  ),
  getSnapshot[0],
  getSnapshot[1]
)

const hasRevalidator =
  EVENT_REVALIDATORS[key] && EVENT_REVALIDATORS[key].length > 0

const cachedData = cached.data

let data = isUndefined(cachedData)
  ? fallback && isPromiseLike(fallback)
    ? use(fallback)
    : fallback
  : cachedData
const error = cached.error

// Use a ref to store previously returned data. Use the initial data as its initial value.
const laggyDataRef = useRef(data)
const consumedCacheDataRef = useRef<ConsumedCacheData | undefined>(UNDEFINED)
let consumedCacheData = consumedCacheDataRef.current
if (!consumedCacheData) {
  consumedCacheData = new WeakMap()
  consumedCacheDataRef.current = consumedCacheData
}
const preloadCacheRef = useRef<{
  data: Data | undefined
  _k: Key
  key: string
  cacheData?: CacheData
} | null>(null)

let returnedData = keepPreviousData
  ? isUndefined(cachedData)
    ? // checking undefined to avoid null being fallback as well
      isUndefined(laggyDataRef.current)
      ? data
      : laggyDataRef.current
    : cachedData
  : data

const hasKeyButNoData = key && isUndefined(data)
const hydrationRef = useRef<boolean | null>(null)
// Note: the conditionally hook call is fine because the environment
// `IS_SERVER` never changes.
// @ts-expect-error -- use hydrationRef directly
const _ =
  !IS_SERVER &&
  // getServerSnapshot is only called during hydration
  // eslint-disable-next-line react-hooks/rules-of-hooks
  useSyncExternalStore(
    sub,
    () => {
      hydrationRef.current = false
      return hydrationRef
    },
    () => {
      hydrationRef.current = true
      return hydrationRef
    }
  )

const isHydration = hydrationRef.current
// During the initial SSR render, warn if the key has no data pre-fetched via:
// - fallback data
// - preload calls
// - initial data from the cache provider
// We only warn once for each key during Hydration.
if (
  strictServerPrefetchWarning &&
  isHydration &&
  !suspense &&
  hasKeyButNoData
) {
  console.warn(
    `Missing pre-initiated data for serialized key "${key}" during server-side rendering. Data fetching should be initiated on the server and provided to SWR via fallback data. You can set "strictServerPrefetchWarning: false" to disable this warning.`
  )
}

// Resolve the default validating state:
// If it's able to validate, and it should revalidate when mount, this will be true.
// - Suspense mode and there's stale data for the initial render.
// - Not suspense mode and there is no fallback data and `revalidateIfStale` is enabled.
// - `revalidateIfStale` is enabled but `data` is not defined.
const shouldDoInitialRevalidation = (() => {
  if (!key || !fetcher) return false
  // If it's paused, we skip revalidation.
  if (getConfig().isPaused()) return false
  // if a key already has revalidators and also has error, we should not trigger revalidation
  if (hasRevalidator && !isUndefined(error)) return false
  // If `revalidateOnMount` is set, we take the value directly.
  if (isInitialMount && !isUndefined(revalidateOnMount))
    return revalidateOnMount
  // cacheData satisfies the initial Suspense render without a duplicate
  // request. Cached data on a later mount follows revalidateIfStale.
  if (suspense && hasCacheData && hasKeyButNoData) return false
  // Under suspense mode, it will always fetch on render if there is no
  // stale data so no need to revalidate immediately mount it again.
  // If data exists, only revalidate if `revalidateIfStale` is true.
  if (suspense) return isUndefined(data) ? false : revalidateIfStale
  // If there is no stale data, we need to revalidate when mount;
  // If `revalidateIfStale` is set to true, we will always revalidate.
  return isUndefined(data) || revalidateIfStale
})()

const defaultValidatingState = isInitialMount && shouldDoInitialRevalidation

const isValidating = isUndefined(cached.isValidating)
  ? defaultValidatingState
  : cached.isValidating
const isLoading = isUndefined(cached.isLoading)
  ? defaultValidatingState
  : cached.isLoading

// The revalidation function is a carefully crafted wrapper of the original
// `fetcher`, to correctly handle the many edge cases.
const revalidate = useCallback(
  async (revalidateOpts?: RevalidatorOptions): Promise<boolean> => {
    const currentFetcher = fetcherRef.current

    if (
      !key ||
      !currentFetcher ||
      unmountedRef.current ||
      getConfig().isPaused()
    ) {
      return false
    }

    let newData: Data
    let startAt: number
    let loading = true
    const opts = revalidateOpts || {}

    // If there is no ongoing concurrent request, or `dedupe` is not set, a
    // new request should be initiated.
    const shouldStartNewRequest = !FETCH[key] || !opts.dedupe
    const shouldUseRSCPreload =
      hasCacheData &&
      !isCacheDataConsumed(consumedCacheData, serverCacheData, key) &&
      !isUndefined(preloadedData) &&
      isUndefined(getCache().data)

/*
   For React 17
   Do unmount check for calls:
   If key has changed during the revalidation, or the component has been
   unmounted, old dispatch and old event callbacks should not take any
   effect

  For React 18
  only check if key has changed
  https://github.com/reactwg/react-18/discussions/82
*/
const callbackSafeguard = () => {
  if (IS_REACT_LEGACY) {
    return (
      !unmountedRef.current &&
      key === keyRef.current &&
      initialMountedRef.current
    )
  }
  return key === keyRef.current
}

// The final state object when the request finishes.
const finalState: State<Data, Error> = {
  isValidating: false,
  isLoading: false
}
const finishRequestAndUpdateState = () => {
  setCache(finalState)
}
const cleanupState = () => {
  // Check if it's still the same request before deleting it.
  const requestInfo = FETCH[key]
  if (requestInfo && requestInfo[1] === startAt) {
    delete FETCH[key]
  }
}

// Start fetching. Change the `isValidating` state, update the cache.
const initialState: State<Data, Error> = { isValidating: true }
// It is in the `isLoading` state, if and only if there is no cached data.
// This bypasses fallback data and laggy data.
if (isUndefined(getCache().data)) {
  initialState.isLoading = true
}
try {
  if (shouldStartNewRequest) {
    setCache(initialState)
    // If no cache is being rendered currently (it shows a blank page),
    // we trigger the loading slow event.
    if (config.loadingTimeout && isUndefined(getCache().data)) {
      setTimeout(() => {
        if (loading && callbackSafeguard()) {
          getConfig().onLoadingSlow(key, config)
        }
      }, config.loadingTimeout)
    }

    // Start the request and save the timestamp.
    // Key must be truthy if entering here.
    if (shouldUseRSCPreload) {
      markCacheDataConsumed(consumedCacheData, serverCacheData, key)
    }
    FETCH[key] = [
      shouldUseRSCPreload
        ? preloadedData
        : currentFetcher(fnArg as DefinitelyTruthy<Key>),
      getTimestamp()
    ]
    if (shouldUseRSCPreload && PRELOAD[key]) {
      delete PRELOAD[key]
    }
  }

  // Wait until the ongoing request is done. Deduplication is also
  // considered here.
  ;[newData, startAt] = FETCH[key]
  newData = await newData

  if (shouldStartNewRequest) {
    // If the request isn't interrupted, clean it up after the
    // deduplication interval.
    setTimeout(cleanupState, config.dedupingInterval)
  }

  // If there're other ongoing request(s), started after the current one,
  // we need to ignore the current one to avoid possible race conditions:
  //   req1------------------>res1        (current one)
  //        req2---------------->res2
  // the request that fired later will always be kept.
  // The timestamp maybe be `undefined` or a number
  if (!FETCH[key] || FETCH[key][1] !== startAt) {
    if (shouldStartNewRequest) {
      if (callbackSafeguard()) {
        getConfig().onDiscarded(key)
      }
    }
    return false
  }

  // Clear error.
  finalState.error = UNDEFINED

  // If there're other mutations(s), that overlapped with the current revalidation:
  // case 1:
  //   req------------------>res
  //       mutate------>end
  // case 2:
  //         req------------>res
  //   mutate------>end
  // case 3:
  //   req------------------>res
  //       mutate-------...---------->
  // we have to ignore the revalidation result (res) because it's no longer fresh.
  // meanwhile, a new revalidation should be triggered when the mutation ends.
  const mutationInfo = MUTATION[key]
  if (
    !isUndefined(mutationInfo) &&
    // case 1
    (startAt <= mutationInfo[0] ||
      // case 2
      startAt <= mutationInfo[1] ||
      // case 3
      mutationInfo[1] === 0)
  ) {
    finishRequestAndUpdateState()
    if (shouldStartNewRequest) {
      if (callbackSafeguard()) {
        getConfig().onDiscarded(key)
      }
    }
    return false
  }
  // Deep compare with the latest state to avoid extra re-renders.
  // For local state, compare and assign.
  const cacheData = getCache().data

  // Since the compare fn could be custom fn
  // cacheData might be different from newData even when compare fn returns True
  finalState.data = compare(cacheData, newData) ? cacheData : newData

  // Trigger the successful callback if it's the original request.
  if (shouldStartNewRequest) {
    if (callbackSafeguard()) {
      getConfig().onSuccess(newData, key, config)
    }
  }
} catch (err: any) {
  cleanupState()

  const currentConfig = getConfig()
  const { shouldRetryOnError } = currentConfig

  // Not paused, we continue handling the error. Otherwise, discard it.
  if (!currentConfig.isPaused()) {
    // Get a new error, don't use deep comparison for errors.
    finalState.error = err as Error

    // Error event and retry logic. Only for the actual request, not

        // deduped ones.
        if (shouldStartNewRequest && callbackSafeguard()) {
          currentConfig.onError(err, key, currentConfig)
          if (
            shouldRetryOnError === true ||
            (isFunction(shouldRetryOnError) &&
              shouldRetryOnError(err as Error))
          ) {
            if (
              !getConfig().revalidateOnFocus ||
              !getConfig().revalidateOnReconnect ||
              isActive()
            ) {
              // If it's inactive, stop. It will auto-revalidate when
              // refocusing or reconnecting.
              // When retrying, deduplication is always enabled.
              currentConfig.onErrorRetry(
                err,
                key,
                currentConfig,
                _opts => {
                  const revalidators = EVENT_REVALIDATORS[key]
                  if (revalidators && revalidators[0]) {
                    revalidators[0](
                      revalidateEvents.ERROR_REVALIDATE_EVENT,
                      _opts
                    )
                  }
                },
                {
                  retryCount: (opts.retryCount || 0) + 1,
                  dedupe: true
                }
              )
            }
          }
        }
      }
    }

    // Mark loading as stopped.
    loading = false

    // Update the current hook's state.
    finishRequestAndUpdateState()

    return true
  },
  // `setState` is immutable, and `eventsCallback`, `fnArg`, and
  // `keyValidating` are depending on `key`, so we can exclude them from
  // the deps array.
  //
  // FIXME:
  // `fn` and `config` might be changed during the lifecycle,
  // but they might be changed every render like this.
  // `useSWR('key', () => fetch('/api/'), { suspense: true })`
  // So we omit the values from the deps array
  // even though it might cause unexpected behaviors.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  [key, cache]
)

// Similar to the global mutate but bound to the current cache and key.
// `cache` isn't allowed to change during the lifecycle.
const boundMutate: SWRResponse<Data, Error>['mutate'] = useCallback(
  // Use callback to make sure `keyRef.current` returns latest result every time
  (...args: any[]) => {
    return internalMutate(cache, keyRef.current, ...args)
  },
  // eslint-disable-next-line react-hooks/exhaustive-deps
  []
)

useIsomorphicLayoutEffect(() => {
  const preloaded = preloadCacheRef.current
  if (!preloaded) return

  preloadCacheRef.current = null
  markCacheDataConsumed(consumedCacheData, preloaded.cacheData, preloaded.key)
  if (isUndefined(getCache().data)) {

    setCache({ data: preloaded.data, error: UNDEFINED, _k: preloaded._k })
  }
  if (PRELOAD[preloaded.key]) {
    delete PRELOAD[preloaded.key]
  }
})

// The logic for updating refs.
useIsomorphicLayoutEffect(() => {
  fetcherRef.current = fetcher
  configRef.current = config
  // Handle laggy data updates. If there's cached data of the current key,
  // it'll be the correct reference.
  if (!isUndefined(cachedData)) {
    laggyDataRef.current = cachedData
  }
})

useIsomorphicLayoutEffect(() => {
  if (
    fetcher ||
    !hasCacheData ||
    isUndefined(preloadedData) ||
    isCacheDataConsumed(consumedCacheData, serverCacheData, key) ||
    !isUndefined(getCache().data)
  ) {
    return
  }

  markCacheDataConsumed(consumedCacheData, serverCacheData, key)
  const mutation = MUTATION[key]
  commitCacheData({
    value: preloadedData,
    getCacheData: () => getCache().data,
    canCommit: () =>
      !unmountedRef.current &&
      key === keyRef.current &&
      MUTATION[key] === mutation,
    setCache: state => setCache({ ...state, _k: fnArg })
  })
})

// After mounted or key changed.
useIsomorphicLayoutEffect(() => {
  if (!key) return

  const softRevalidate = revalidate.bind(UNDEFINED, WITH_DEDUPE)

  let nextFocusRevalidatedAt = 0

  if (getConfig().revalidateOnFocus) {
    const initNow = Date.now()
    nextFocusRevalidatedAt = initNow + getConfig().focusThrottleInterval
  }

  // Expose revalidators to global event listeners. So we can trigger
  // revalidation from the outside.
  const onRevalidate = (
    type: RevalidateEvent,
    opts: {
      retryCount?: number
      dedupe?: boolean
      revalidate?: boolean
    } = {}
  ) => {
    if (type == revalidateEvents.FOCUS_EVENT) {
      const now = Date.now()
      if (
        getConfig().revalidateOnFocus &&
        now > nextFocusRevalidatedAt &&
        isActive()
      ) {
        nextFocusRevalidatedAt = now + getConfig().focusThrottleInterval
        softRevalidate()
      }
    } else if (type == revalidateEvents.RECONNECT_EVENT) {
      if (getConfig().revalidateOnReconnect && isActive()) {
        softRevalidate()
      }
    } else if (type == revalidateEvents.MUTATE_EVENT) {

      return revalidate()
    } else if (type == revalidateEvents.ERROR_REVALIDATE_EVENT) {
      return revalidate(opts)
    } else if (type == revalidateEvents.UNLOAD_EVENT) {
      // The cache has been cleared: drop the previous data kept by
      // `keepPreviousData` so it can't stay on screen.
      laggyDataRef.current = UNDEFINED
      if (opts.revalidate) {
        return revalidate()
      }
    }
    return
  }

  const unsubEvents = subscribeCallback(key, EVENT_REVALIDATORS, onRevalidate)

  // Mark the component as mounted and update corresponding refs.
  unmountedRef.current = false
  keyRef.current = key
  initialMountedRef.current = true

  // Keep the original key in the cache.
  setCache({ _k: fnArg })

  // Trigger a revalidation
  if (shouldDoInitialRevalidation) {
    // Performance optimization: if a request is already in progress for this key,
    // skip the revalidation to avoid redundant work
    if (!FETCH[key]) {
      if (isUndefined(data) || IS_SERVER) {
        // Revalidate immediately.
        softRevalidate()
      } else {
        // Delay the revalidate if we have data to return so we won't block
        // rendering.
        rAF(softRevalidate)
      }
    }
  }

  return () => {
    // Mark it as unmounted.
    unmountedRef.current = true

    unsubEvents()
  }
}, [key])

// Polling
useIsomorphicLayoutEffect(() => {
  let timer: any

  function next() {
    // Use the passed interval
    // ...or invoke the function with the updated data to get the interval
    const interval = isFunction(refreshInterval)
      ? refreshInterval(getCache().data)
      : refreshInterval

    // We only start the next interval if `refreshInterval` is not 0, and:
    // - `force` is true, which is the start of polling
    // - or `timer` is not 0, which means the effect wasn't canceled
    if (interval && timer !== -1) {
      timer = setTimeout(execute, interval)
    }
  }

  function execute() {
    // Check if it's OK to execute:
    // Only revalidate when the page is visible, online, and not errored.
    if (
      !getCache().error &&
      (refreshWhenHidden || getConfig().isVisible()) &&
      (refreshWhenOffline || getConfig().isOnline())
    ) {
      revalidate(WITH_DEDUPE).then(next)
    } else {
      // Schedule the next interval to check again.
      next()
    }

  }

  next()

  return () => {
    if (timer) {
      clearTimeout(timer)
      timer = -1
    }
  }
}, [refreshInterval, refreshWhenHidden, refreshWhenOffline, key])

// Display debug info in React DevTools.
useDebugValue(returnedData)

// In Suspense mode, we can't return the empty `data` state.
// If there is an `error`, the `error` needs to be thrown to the error boundary.
// If there is no `error`, the `revalidation` promise needs to be thrown to
// the suspense boundary.
if (suspense) {
  // SWR should throw when trying to use Suspense on the server with React 18,
  // without providing any fallback data. This causes hydration errors. See:
  // https://github.com/vercel/swr/issues/1832
  if (
    !IS_REACT_LEGACY &&
    IS_SERVER &&
    hasKeyButNoData &&
    isUndefined(preloadedData)
  ) {
    throw new Error('Fallback data is required when using Suspense in SSR.')
  }

  // Always update fetcher and config refs even with the Suspense mode.
  if (hasKeyButNoData) {
    fetcherRef.current = fetcher
    configRef.current = config
    unmountedRef.current = false
  }

  const shouldConsumePreload = !isUndefined(preloadedData) && hasKeyButNoData
  let preloadData = UNDEFINED as Data | undefined

  if (shouldConsumePreload && hasCacheData) {
    preloadData =
      preloadedData && isPromiseLike(preloadedData)
        ? use(preloadedData)
        : preloadedData
    data = preloadData
    returnedData = preloadData

    if (!IS_SERVER) {
      preloadCacheRef.current = {
        data: preloadData,
        _k: fnArg,
        key,
        cacheData: serverCacheData
      }
    }
  } else {
    const mutateReq = shouldConsumePreload
      ? boundMutate(preloadedData)
      : resolvedUndef
    use(mutateReq)
  }

  if (!isUndefined(error) && hasKeyButNoData) {
    throw error
  }
  const revalidation =
    hasKeyButNoData && isUndefined(preloadData)
      ? revalidate(WITH_DEDUPE)
      : resolvedUndef
  if (!isUndefined(returnedData) && hasKeyButNoData) {
    // @ts-ignore modify react promise status
    revalidation.status = 'fulfilled'
    // @ts-ignore modify react promise value
    revalidation.value = true
  }
  use(revalidation)
}

  const swrResponse: SWRResponse<Data, Error> = {
    mutate: boundMutate,
    get data() {
      stateDependencies.data = true
      return returnedData
    },
    get error() {
      stateDependencies.error = true
      return error
    },
    get isValidating() {
      stateDependencies.isValidating = true
      return isValidating
    },
    get isLoading() {
      stateDependencies.isLoading = true
      return isLoading
    }
  }
  return swrResponse
}

export const SWRConfig = OBJECT.defineProperty(ConfigProvider, 'defaultValue', {
  value: defaultConfig
}) as typeof ConfigProvider & {
  defaultValue: FullConfiguration
}

export { unstable_serialize } from './serialize'

/**
 * A hook to fetch data.
 *
 * @see {@link https://swr.vercel.app}
 *
 * @example
 * ```jsx
 * import useSWR from 'swr'
 * function Profile() {
 *   const { data, error, isLoading } = useSWR('/api/user', fetcher)
 *   if (error) return <div>failed to load</div>
 *   if (isLoading) return <div>loading...</div>
 *   return <div>hello {data.name}!</div>
 * }
 * ```
 */
const useSWR = withArgs<SWRHook>(useSWRHandler)

export default useSWR

export const infinite = (<Data, Error>(useSWRNext: SWRHook) =>
  (
    getKey: SWRInfiniteKeyLoader,
    fn: BareFetcher<Data> | null,
    config: Omit<typeof SWRConfig.defaultValue, 'fetcher'> &
      Omit<SWRInfiniteConfiguration<Data, Error>, 'fetcher'>
  ) => {
    const didMountRef = useRef<boolean>(false)
    const {
      cache,
      initialSize = 1,
      revalidateAll = false,
      persistSize = false,
      revalidateFirstPage = true,
      revalidateOnMount = false,
      parallel = false
    } = config
    const [, , , PRELOAD] = SWRGlobalState.get(defaultCache) as GlobalState

    // The serialized key of the first page. This key will be used to store
    // metadata of this SWR infinite hook.
    let infiniteKey: string | undefined
    try {
      infiniteKey = getFirstPageKey(getKey)
      if (infiniteKey) infiniteKey = INFINITE_PREFIX + infiniteKey
    } catch (err) {
      // Not ready yet.
    }

    const [get, set, subscribeCache] = createCacheHelper<
      Data,
      SWRInfiniteCacheValue<Data, any>
    >(cache, infiniteKey)

    const getSnapshot = useCallback(() => {
      const size = isUndefined(get()._l) ? initialSize : get()._l
      return size
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [cache, infiniteKey, initialSize])
    useSyncExternalStore(
      useCallback(
        (callback: () => void) => {
          if (infiniteKey)
            return subscribeCache(infiniteKey, () => {
              callback()
            })
          return () => {}
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [cache, infiniteKey]
      ),
      getSnapshot,
      getSnapshot
    )

    const resolvePageSize = useCallback((): number => {
      const cachedPageSize = get()._l
      return isUndefined(cachedPageSize) ? initialSize : cachedPageSize

      // `cache` isn't allowed to change during the lifecycle
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [infiniteKey, initialSize])
    // keep the last page size to restore it with the persistSize option
    const lastPageSizeRef = useRef<number>(resolvePageSize())

    // When the page key changes, we reset the page size if it's not persisted
    useIsomorphicLayoutEffect(() => {
      if (!didMountRef.current) {
        didMountRef.current = true
        return
      }

      if (infiniteKey) {
        // If the key has been changed, we keep the current page size if persistSize is enabled
        // Otherwise, we reset the page size to cached pageSize
        set({ _l: persistSize ? lastPageSizeRef.current : resolvePageSize() })
      }

      // `initialSize` isn't allowed to change during the lifecycle
    }, [infiniteKey, cache])

// Needs to check didMountRef during mounting, not in the fetcher
const shouldRevalidateOnMount = revalidateOnMount && !didMountRef.current

// Actual SWR hook to load all pages in one fetcher.
const swr = useSWRNext(
  infiniteKey,
  async key => {
    // get the revalidate context
    const forceRevalidateAll = get()._i
    const shouldRevalidatePage = get()._r
    // Capture the cache's unload generation (bumped by every `unload()`
    // call) so page responses that resolve after an unload are not
    // written back to the cleared cache.
    const state = SWRGlobalState.get(cache) as GlobalState
    const unloadGeneration = state[8]
    const unloadedDuringRequest = () => state[8] !== unloadGeneration
    set({ _r: UNDEFINED })

    // return an array of page data
    const data: Data[] = []

    const pageSize = resolvePageSize()
    const [getCache] = createCacheHelper<
      Data,
      SWRInfiniteCacheValue<Data[], any>
    >(cache, key)
    const cacheData = getCache().data

    const revalidators = []

    let previousPageData = null
    for (let i = 0; i < pageSize; ++i) {
      const [pageKey, pageArg] = serialize(
        getKey(i, parallel ? null : previousPageData)
      )

      if (!pageKey) {
        // `pageKey` is falsy, stop fetching new pages.
        break
      }

      const [getSWRCache, setSWRCache] = createCacheHelper<
        Data,
        SWRInfiniteCacheValue<Data, any>
      >(cache, pageKey)

      // Get the cached page data.
      let pageData = getSWRCache().data as Data
      // should fetch (or revalidate) if:
      // - `revalidateAll` is enabled
      // - `mutate()` called
      // - the cache is missing
      // - it's the first page and it's not the initial render
      // - `revalidateOnMount` is enabled and it's on mount
      // - cache for that page has changed
      const shouldFetchPage =
        revalidateAll ||
        forceRevalidateAll ||
        isUndefined(pageData) ||
        (revalidateFirstPage && !i && !isUndefined(cacheData)) ||
        shouldRevalidateOnMount ||
        (cacheData &&
          !isUndefined(cacheData[i]) &&
          !config.compare(cacheData[i], pageData))
      if (
        fn &&
        (typeof shouldRevalidatePage === 'function'
          ? shouldRevalidatePage(pageData, pageArg)
          : shouldFetchPage)
      ) {
        const revalidate = async () => {
          const hasPreloadedRequest = pageKey in PRELOAD
          if (!hasPreloadedRequest) {
            pageData = await fn(pageArg)
          } else {
            const req = PRELOAD[pageKey]
            // delete the preload cache key before resolving it
            // in case there's an error
            delete PRELOAD[pageKey]

            // get the page data from the preload cache
            pageData = await req
          }
          if (!unloadedDuringRequest()) {
            setSWRCache({ data: pageData, _k: pageArg })
          }
          data[i] = pageData
        }
        if (parallel) {
          revalidators.push(revalidate)
        } else {
          await revalidate()
        }
      } else {
        data[i] = pageData
      }
      if (!parallel) {
        previousPageData = pageData
      }
    }

    // flush all revalidateions in parallel
    if (parallel) {
      await Promise.all(revalidators.map(r => r()))
    }

    // once we executed the data fetching based on the context, clear the
    // context. Skipped after an unload so the cleared meta entry isn't
    // re-created.
    if (!unloadedDuringRequest()) {
      set({ _i: UNDEFINED })
    }

    // return the data
    return data
  },
  config
)

const mutate = useCallback(
  // eslint-disable-next-line func-names
  function <T = Data[]>(
    data?:
      | undefined
      | Data[]
      | Promise<Data[] | undefined>
      | MutatorCallback<Data[]>,
    opts?: undefined | boolean | SWRInfiniteMutatorOptions<Data[], T>
  ) {
    // When passing as a boolean, it's explicitly used to disable/enable
    // revalidation.
    const options =
      typeof opts === 'boolean' ? { revalidate: opts } : opts || {}

    // Default to true.
    const shouldRevalidate = options.revalidate !== false

    // It is possible that the key is still falsy.
    if (!infiniteKey) return EMPTY_PROMISE
    if (shouldRevalidate) {
      if (!isUndefined(data)) {
        // We only revalidate the pages that are changed
        set({ _i: false, _r: options.revalidate })
      } else {
        // Calling `mutate()`, we revalidate all pages
        set({ _i: true, _r: options.revalidate })
      }
    }

    return arguments.length
      ? swr.mutate(data, { ...options, revalidate: shouldRevalidate })
      : swr.mutate()
  },
  // swr.mutate is always the same reference
  // eslint-disable-next-line react-hooks/exhaustive-deps
  [infiniteKey, cache]
)
// Extend the SWR API

const setSize = useCallback(

    (arg: number | ((size: number) => number)) => {
      // It is possible that the key is still falsy.
      if (!infiniteKey) return EMPTY_PROMISE
      const [, changeSize] = createCacheHelper<
        Data,
        SWRInfiniteCacheValue<Data, any>
      >(cache, infiniteKey)
      let size
      if (isFunction(arg)) {
        size = arg(resolvePageSize())
      } else if (typeof arg == 'number') {
        size = arg
      }
      if (typeof size != 'number') return EMPTY_PROMISE

      changeSize({ _l: size })
      lastPageSizeRef.current = size

      // Calculate the page data after the size change.
      const data: Data[] = []
      const [getInfiniteCache] = createCacheHelper<
        Data,
        SWRInfiniteCacheValue<Data[], any>
      >(cache, infiniteKey)
      let previousPageData = null
      for (let i = 0; i < size; ++i) {
        const [pageKey] = serialize(getKey(i, previousPageData))
        const [getCache] = createCacheHelper<
          Data,
          SWRInfiniteCacheValue<Data, any>
        >(cache, pageKey)
        // Get the cached page data.
        const pageData = pageKey ? getCache().data : UNDEFINED

        // Call `mutate` with infinte cache data if we can't get it from the page cache.
        if (isUndefined(pageData)) {
          return mutate(getInfiniteCache().data)
        }

        data.push(pageData)
        previousPageData = pageData
      }
      return mutate(data)
    },
    // exclude getKey from the dependencies, which isn't allowed to change during the lifecycle
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [infiniteKey, cache, mutate, resolvePageSize]
  )

  // Use getter functions to avoid unnecessary re-renders caused by triggering
  // all the getters of the returned swr object.
  return {
    size: resolvePageSize(),
    setSize,
    mutate,
    get data() {
      return swr.data
    },
    get error() {
      return swr.error
    },
    get isValidating() {
      return swr.isValidating
    },
    get isLoading() {
      return swr.isLoading
    }
  }
}) as unknown as Middleware

import type { SWRInfiniteKeyLoader } from './types'
import { serialize } from '../_internal/utils/serialize'
import { INFINITE_PREFIX } from '../_internal/constants'

export const getFirstPageKey = (getKey: SWRInfiniteKeyLoader) => {
  return serialize(getKey ? getKey(0, null) : null)[0]
}

export const unstable_serialize = (getKey: SWRInfiniteKeyLoader) => {
  return INFINITE_PREFIX + getFirstPageKey(getKey)
}

export interface SWRInfiniteConfiguration<
  Data = any,
  Error = any,
  Fn extends SWRInfiniteFetcher<Data> = BareFetcher<Data>
> extends Omit<SWRConfiguration<Data[], Error>, 'compare'> {
  initialSize?: number
  revalidateAll?: boolean
  persistSize?: boolean
  revalidateFirstPage?: boolean
  parallel?: boolean
  fetcher?: Fn
  compare?: SWRInfiniteCompareFn<Data>
}

interface SWRInfiniteRevalidateFn<Data = any> {
  (data: Data, key: Arguments): boolean
}

export type SWRInfiniteKeyedMutator<Data> = <MutationData = Data>(
  data?: Data | Promise<Data | undefined> | MutatorCallback<Data>,
  opts?: boolean | SWRInfiniteMutatorOptions<Data, MutationData>
) => Promise<Data | MutationData | undefined>

export interface SWRInfiniteResponse<Data = any, Error = any> extends Omit<
  SWRResponse<Data[], Error>,
  'mutate'
> {
  size: number
  setSize: (
    size: number | ((_size: number) => number)
  ) => Promise<Data[] | undefined>
  mutate: SWRInfiniteKeyedMutator<Data[]>
}

export interface SWRInfiniteCacheValue<Data = any, Error = any> extends State<
  Data,
  Error
> {
  // We use cache to pass extra info (context) to fetcher so it can be globally
  // shared. The key of the context data is based on the first-page key.
  _i?: boolean
  // Page size is also cached to share the page data between hooks with the
  // same key.
  _l?: number
  _k?: Arguments
  _r?: boolean | SWRInfiniteRevalidateFn
}

const mutation = (<Data, Error>() =>
  (
    key: Key,
    fetcher: MutationFetcher<Data>,
    config: SWRMutationConfiguration<Data, Error> = {}
  ) => {
    const { mutate } = useSWRConfig()
    const keyRef = useRef(key)
    const fetcherRef = useRef(fetcher)
    const configRef = useRef(config)
    // Ditch all mutation results that happened earlier than this timestamp.
    const ditchMutationsUntilRef = useRef(0)

    const [stateRef, stateDependencies, setState] = useStateWithDeps<{
      data: Data | undefined
      error: Error | undefined
      isMutating: boolean
    }>({
      data: UNDEFINED,
      error: UNDEFINED,
      isMutating: false
    })

    const currentState = stateRef.current

    const trigger = useCallback(
      async (arg: any, opts?: SWRMutationConfiguration<Data, Error>) => {
        const [serializedKey, resolvedKey] = serialize(keyRef.current)

        if (!fetcherRef.current) {
          throw new Error('Can’t trigger the mutation: missing fetcher.')
        }
        if (!serializedKey) {
          throw new Error('Can’t trigger the mutation: missing key.')
        }

        // Disable cache population by default.
        const options = mergeObjects(
          mergeObjects(
            { populateCache: false, throwOnError: true },
            configRef.current
          ),
          opts
        )

        // Trigger a mutation, and also track the timestamp. Any mutation that happened
        // earlier this timestamp should be ignored.
        const mutationStartedAt = getTimestamp()

        ditchMutationsUntilRef.current = mutationStartedAt

        setState({ isMutating: true })

        try {
          const data = await mutate<Data>(
            serializedKey,
            (fetcherRef.current as any)(resolvedKey, { arg }),
            // We must throw the error here so we can catch and update the states.
            mergeObjects(options, { throwOnError: true })
          )

          // If it's reset after the mutation, we don't broadcast any state change.
          if (ditchMutationsUntilRef.current <= mutationStartedAt) {
            startTransition(() =>
              setState({ data, isMutating: false, error: undefined })
            )
            options.onSuccess?.(data as Data, serializedKey, options)
          }
          return data
        } catch (error) {
          // If it's reset after the mutation, we don't broadcast any state change
          // or throw because it's discarded.
          if (ditchMutationsUntilRef.current <= mutationStartedAt) {
            startTransition(() =>
              setState({ error: error as Error, isMutating: false })
            )
            options.onError?.(error as Error, serializedKey, options)
            if (options.throwOnError) {
              throw error as Error
            }

          }
        }
      },
      // eslint-disable-next-line react-hooks/exhaustive-deps
      []
    )

    const reset = useCallback(() => {
      ditchMutationsUntilRef.current = getTimestamp()
      setState({ data: UNDEFINED, error: UNDEFINED, isMutating: false })
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [])

    useIsomorphicLayoutEffect(() => {
      keyRef.current = key
      fetcherRef.current = fetcher
      configRef.current = config
    })

    // We don't return `mutate` here as it can be pretty confusing (e.g. people
    // calling `mutate` but they actually mean `trigger`).
    // And also, `mutate` relies on the useSWR hook to exist too.
    return {
      trigger,
      reset,
      get data() {
        stateDependencies.data = true
        return currentState.data
      },
      get error() {
        stateDependencies.error = true
        return currentState.error
      },
      get isMutating() {
        stateDependencies.isMutating = true
        return currentState.isMutating
      }
    }
  }) as unknown as Middleware

/**
 * A hook to define and manually trigger remote mutations like POST, PUT, DELETE and PATCH use cases.
 *
 * @link https://swr.vercel.app/docs/mutation
 * @example
 * ```jsx
 * import useSWRMutation from 'swr/mutation'
 *
 * const {
 *   data,
 *   error,
 *   trigger,
 *   reset,
 *   isMutating
 * } = useSWRMutation(key, fetcher, options?)
 * ```
 */

export const startTransition: (scope: TransitionFunction) => void =
  IS_REACT_LEGACY
    ? cb => {
        cb()
      }
    : React.startTransition

/**
 * An implementation of state with dependency-tracking.
 * @param initialState - The initial state object.
 */

export const useStateWithDeps = <S = Record<string, any>>(
  initialState: S
): [
  MutableRefObject<S>,
  Record<keyof S, boolean>,
  (payload: Partial<S>) => void
] => {
  const [, rerender] = useState<Record<string, unknown>>({})
  const unmountedRef = useRef(false)
  const stateRef = useRef<S>(initialState)

  // If a state property (data, error, or isValidating) is accessed by the render
  // function, we mark the property as a dependency so if it is updated again
  // in the future, we trigger a rerender.
  // This is also known as dependency-tracking.
  const stateDependenciesRef = useRef<Record<keyof S, boolean>>({
    data: false,
    error: false,
    isValidating: false
  } as Record<keyof S, boolean>)

  /**
   * Updates state and triggers re-render if necessary.
   * @param payload To change stateRef, pass the values explicitly to setState:
   * @example
   * ```js
   * setState({
   *   isValidating: false
   *   data: newData // set data to newData
   *   error: undefined // set error to undefined
   * })
   *
   * setState({
   *   isValidating: false
   *   data: undefined // set data to undefined
   *   error: err // set error to err
   * })
   * ```
   */
  const setState = useCallback((payload: Partial<S>) => {
    let shouldRerender = false

    const currentState = stateRef.current
    for (const key in payload) {
      if (Object.prototype.hasOwnProperty.call(payload, key)) {
        const k = key as keyof S

        // If the property has changed, update the state and mark rerender as
        // needed.
        if (currentState[k] !== payload[k]) {
          currentState[k] = payload[k]!

          // If the property is accessed by the component, a rerender should be
          // triggered.
          if (stateDependenciesRef.current[k]) {
            shouldRerender = true
          }
        }
      }
    }

    if (shouldRerender && !unmountedRef.current) {
      rerender({})
    }
  }, [])

  useIsomorphicLayoutEffect(() => {
    unmountedRef.current = false
    return () => {
      unmountedRef.current = true
    }
  })

  return [stateRef, stateDependenciesRef.current, setState]
}

import type { SWRResponse, Key, Arguments } from '../index'

type FetcherResponse<Data> = Data | Promise<Data>

type FetcherOptions<ExtraArg = unknown> = Readonly<{
  arg: ExtraArg
}>

import type {
  Key,
  SWRHook,
  Middleware,
  SWRConfiguration,
  SWRConfig
} from '../index'
import type {
  SWRSubscriptionOptions,
  SWRSubscription,
  SWRSubscriptionResponse,
  SWRSubscriptionHook
} from './types'
import useSWR from '../index'
import {
  withMiddleware,
  serialize,
  useIsomorphicLayoutEffect,
  createCacheHelper
} from '../_internal'

// [subscription count, disposer]
type SubscriptionStates = [Map<string, number>, Map<string, () => void>]
const subscriptionStorage = new WeakMap<object, SubscriptionStates>()

const SUBSCRIPTION_PREFIX = '$sub$'

export const subscription = (<Data = any, Error = any>(useSWRNext: SWRHook) =>
  (
    _key: Key,
    subscribe: SWRSubscription<any, Data, Error>,
    config: SWRConfiguration & typeof SWRConfig.defaultValue
  ): SWRSubscriptionResponse<Data, Error> => {
    const [key, args] = serialize(_key)

    // Prefix the key to avoid conflicts with other SWR resources.
    const subscriptionKey = key ? SUBSCRIPTION_PREFIX + key : undefined
    const swr = useSWRNext(subscriptionKey, null, config)

    const { cache } = config

    // Ensure that the subscription state is scoped by the cache boundary, so
    // you can have multiple SWR zones with subscriptions having the same key.
    if (!subscriptionStorage.has(cache)) {
      subscriptionStorage.set(cache, [
        new Map<string, number>(),
        new Map<string, () => void>()
      ])
    }

    const [subscriptions, disposers] = subscriptionStorage.get(cache)!

    useIsomorphicLayoutEffect(() => {
      if (!subscriptionKey) return

      const [, set] = createCacheHelper<Data>(cache, subscriptionKey)
      const refCount = subscriptions.get(subscriptionKey) || 0

      const next: SWRSubscriptionOptions<Data, Error>['next'] = (
        error,
        data
      ) => {
        if (error !== null && typeof error !== 'undefined') {
          set({ error })
        } else {
          set({ error: undefined })
          swr.mutate(data, false)
        }
      }

      // Increment the ref count.
      subscriptions.set(subscriptionKey, refCount + 1)

      if (!refCount) {
        const dispose = subscribe(args, { next })
        if (typeof dispose !== 'function') {
          throw new Error(
            'The `subscribe` function must return a function to unsubscribe.'
          )
        }
        disposers.set(subscriptionKey, dispose)
      }

      return () => {
        const count = subscriptions.get(subscriptionKey)! - 1

        subscriptions.set(subscriptionKey, count)

        // Dispose if it's the last one.
        if (!count) {
          const dispose = disposers.get(subscriptionKey)
          dispose?.()

          // Remove both entries, so the internal states only retain the
          // subscription keys that currently have active subscribers.
          subscriptions.delete(subscriptionKey)
          disposers.delete(subscriptionKey)
        }
      }
    }, [subscriptionKey])

    return {
      get data() {
        return swr.data
      },
      get error() {
        return swr.error

      }
    }
  }) as unknown as Middleware

/**
 * A hook to subscribe a SWR resource to an external data source for continuous updates.
 * @experimental This API is experimental and might change in the future.
 * @example
 * ```jsx
 * import useSWRSubscription from 'swr/subscription'
 *
 * const { data, error } = useSWRSubscription(key, (key, { next }) => {
 *   const unsubscribe = dataSource.subscribe(key, (err, data) => {
 *     next(err, data)
 *   })
 *   return unsubscribe
 * })
 * ```
 */

const useSWRSubscription = withMiddleware(
  useSWR,
  subscription
) as SWRSubscriptionHook

export default useSWRSubscription

export type {
  SWRSubscription,
  SWRSubscriptionOptions,
  SWRSubscriptionResponse,
  SWRSubscriptionHook
}

import type { Key, SWRConfiguration, MutatorCallback } from '../index'

export type SWRSubscriptionOptions<Data = any, Error = any> = {
  next: (err?: Error | null, data?: Data | MutatorCallback<Data>) => void
}
